window.QUIZ_BANK['javascript'] = (window.QUIZ_BANK['javascript']||[]).concat([
{id:1211,topic:'javascript',difficulty:'intermediate',question:'What does `Array.from({length:3}, (_,i) => i*2)` produce?',options:['[0,2,4]','[1,2,3]','[0,1,2]','[2,4,6]'],answer:0,explanation:'Array.from with a map function uses the index i. i*2 for indices 0,1,2 gives [0,2,4].'},
{id:1212,topic:'javascript',difficulty:'beginner',question:'Which operator checks both value and type equality?',options:['==','===','=','!='],answer:1,explanation:'=== (strict equality) checks both value and type without coercion, while == performs type coercion before comparing.'},
{id:1213,topic:'javascript',difficulty:'intermediate',question:'What is the output of `typeof null`?',options:['"null"','"object"','"undefined"','"boolean"'],answer:1,explanation:'typeof null returns "object" — a historic bug in JavaScript that cannot be changed without breaking existing code.'},
{id:1214,topic:'javascript',difficulty:'intermediate',question:'What does the `in` operator check?',options:['Whether a value exists in an array','Whether a property exists in an object or its prototype chain','Whether a variable is defined','Whether a string contains a substring'],answer:1,explanation:'The in operator returns true if the specified property exists in the object or its prototype chain, e.g., "key" in obj.'},
{id:1215,topic:'javascript',difficulty:'beginner',question:'What does `Array.isArray([])` return?',options:['false','true','undefined','null'],answer:1,explanation:'Array.isArray() returns true for arrays and false for non-arrays. It is the reliable way to check if a value is an array.'},
{id:1216,topic:'javascript',difficulty:'advanced',question:'What is a WeakMap?',options:['A Map with weak references to values','A Map with weak references to keys that allows garbage collection','A Map limited to 100 entries','A read-only Map'],answer:1,explanation:'A WeakMap holds weak references to its keys (which must be objects), allowing keys to be garbage-collected when no other references exist. It is non-iterable.'},
{id:1217,topic:'javascript',difficulty:'intermediate',question:'What does `"5" - 3` evaluate to?',options:['NaN','"53"','2','8'],answer:2,explanation:'The minus operator does not do string concatenation; it coerces "5" to the number 5. 5 - 3 = 2.'},
{id:1218,topic:'javascript',difficulty:'intermediate',question:'What does `"5" + 3` evaluate to?',options:['8','"53"','NaN','53'],answer:1,explanation:'The + operator with a string operand performs concatenation. "5" + 3 converts 3 to "3" and concatenates to produce "53".'},
{id:1219,topic:'javascript',difficulty:'beginner',question:'Which method removes the last element from an array and returns it?',options:['shift()','pop()','splice()','slice()'],answer:1,explanation:'Array.pop() removes and returns the last element. shift() removes the first element. slice() returns a copy. splice() inserts/removes at any position.'},
{id:1220,topic:'javascript',difficulty:'intermediate',question:'What is the difference between `let` and `var`?',options:['var is block-scoped; let is function-scoped','let is block-scoped; var is function/global-scoped','They are identical','let allows reassignment; var does not'],answer:1,explanation:'let is block-scoped (limited to the enclosing {}). var is function-scoped (or global if outside a function) and is hoisted to the top of its scope.'},
{id:1221,topic:'javascript',difficulty:'intermediate',question:'What does `Promise.allSettled()` do?',options:['Rejects as soon as any promise rejects','Fulfills only when all promises fulfill','Waits for all promises regardless of outcome and returns their statuses','Returns the first settled promise'],answer:2,explanation:'Promise.allSettled() waits for all promises to settle (fulfill or reject) and returns an array of outcome objects with status "fulfilled" or "rejected".'},
{id:1222,topic:'javascript',difficulty:'beginner',question:'How do you declare a constant in JavaScript?',options:['let x = 1','var x = 1','const x = 1','constant x = 1'],answer:2,explanation:'const declares a block-scoped variable whose binding cannot be reassigned. Note: const objects can still have their properties mutated.'},
{id:1223,topic:'javascript',difficulty:'advanced',question:'What does `Object.freeze()` do?',options:['Prevents adding new properties but allows modification of existing ones','Prevents all modifications: adding, deleting, and changing properties','Makes the object immutable recursively (deep freeze)','Converts the object to a primitive'],answer:1,explanation:'Object.freeze() makes an object shallow-immutable: prevents adding/removing/changing properties. It does not deep-freeze nested objects.'},
{id:1224,topic:'javascript',difficulty:'intermediate',question:'What is event bubbling?',options:['An event that fires repeatedly','An event propagating from the target element up to the document root','An event propagating from the document root down to the target','An event that only fires once'],answer:1,explanation:'Event bubbling is the propagation phase where an event starts at the target element and bubbles up through its ancestors to the document root.'},
{id:1225,topic:'javascript',difficulty:'intermediate',question:'What does `e.stopPropagation()` do?',options:['Prevents the default browser behavior','Stops the event from bubbling or capturing further','Removes the event listener','Cancels the event entirely'],answer:1,explanation:'stopPropagation() stops the event from propagating further through the bubbling or capturing phase, but does not prevent the default action.'},
{id:1226,topic:'javascript',difficulty:'beginner',question:'Which statement is true about arrow functions and `this`?',options:['Arrow functions have their own `this` binding','Arrow functions inherit `this` from the enclosing lexical scope','Arrow functions always bind `this` to the global object','Arrow functions cannot access `this`'],answer:1,explanation:'Arrow functions do not have their own this. They capture the this value from the surrounding lexical context at the time of definition.'},
{id:1227,topic:'javascript',difficulty:'intermediate',question:'What is the output of `[1,2,3].reduce((acc,val) => acc + val, 0)`?',options:['1','3','6','0'],answer:2,explanation:'reduce accumulates: 0+1=1, 1+2=3, 3+3=6. Starting accumulator is 0, so the final result is 6.'},
{id:1228,topic:'javascript',difficulty:'advanced',question:'What is a Proxy in JavaScript?',options:['A copy of an object','An object that wraps another and intercepts operations on it','A read-only view of an object','A serialized version of an object'],answer:1,explanation:'A Proxy wraps a target object and defines traps (handlers) for fundamental operations like get, set, has, deleteProperty, etc., enabling meta-programming.'},
{id:1229,topic:'javascript',difficulty:'intermediate',question:'What does `Object.keys()` return?',options:['An array of the object\'s own enumerable symbol keys','An array of the object\'s own enumerable string-keyed property names','All keys including inherited ones','An iterator of key-value pairs'],answer:1,explanation:'Object.keys() returns an array of the object\'s own (not inherited) enumerable string-keyed property names.'},
{id:1230,topic:'javascript',difficulty:'beginner',question:'What is `NaN`?',options:['A number type value representing "Not a Number"','The string "NaN"','null','undefined'],answer:0,explanation:'NaN (Not a Number) is a special numeric value of type "number". It results from invalid numeric operations like 0/0 or parseInt("abc").'},
{id:1231,topic:'javascript',difficulty:'intermediate',question:'What does `isNaN("hello")` return?',options:['false','true','undefined','NaN'],answer:1,explanation:'isNaN() coerces the argument to a number first. "hello" becomes NaN, so isNaN("hello") returns true. Use Number.isNaN() for strict checks without coercion.'},
{id:1232,topic:'javascript',difficulty:'intermediate',question:'What does `Number.isNaN("hello")` return?',options:['true','false','undefined','NaN'],answer:1,explanation:'Number.isNaN() does NOT coerce. It returns true only if the value is literally the NaN value of type number. "hello" is a string, so it returns false.'},
{id:1233,topic:'javascript',difficulty:'advanced',question:'What is the temporal dead zone (TDZ)?',options:['The time a promise is pending','The period between the start of a block scope and the initialization of a let/const variable','The time between page load and script execution','A deprecated JS feature'],answer:1,explanation:'The TDZ is the period from the start of the enclosing block until the let/const declaration is encountered. Accessing the variable in TDZ throws a ReferenceError.'},
{id:1234,topic:'javascript',difficulty:'intermediate',question:'Which method tests whether at least one element passes the provided function?',options:['every()','find()','some()','includes()'],answer:2,explanation:'Array.some() returns true if at least one element satisfies the callback. every() requires all elements to pass. find() returns the first matching element.'},
{id:1235,topic:'javascript',difficulty:'intermediate',question:'What does `Array.prototype.flat(Infinity)` do?',options:['Creates a flat array by removing all values','Recursively flattens a nested array to any depth','Flattens exactly one level','Returns the array unchanged'],answer:1,explanation:'flat(Infinity) recursively flattens all levels of nesting in an array, e.g., [1,[2,[3]]] becomes [1,2,3].'},
{id:1236,topic:'javascript',difficulty:'beginner',question:'What is a template literal?',options:['A string using single quotes','A string enclosed in backticks that supports interpolation and multi-line','A regular expression literal','A tagged union type'],answer:1,explanation:'Template literals use backticks (`) and support embedded expressions via ${expression}, multi-line strings, and tagged templates.'},
{id:1237,topic:'javascript',difficulty:'intermediate',question:'What is destructuring assignment?',options:['Deleting properties from an object','Extracting values from arrays or properties from objects into distinct variables','Copying an object','Merging two objects'],answer:1,explanation:'Destructuring lets you unpack values from arrays or properties from objects into variables: const {a,b} = obj or const [x,y] = arr.'},
{id:1238,topic:'javascript',difficulty:'intermediate',question:'What does the spread operator `...` do when used with an array?',options:['Joins two arrays','Expands an iterable into individual elements','Filters an array','Creates a deep copy of an array'],answer:1,explanation:'The spread operator expands an iterable (array, string, etc.) into its individual elements, e.g., [...arr1, ...arr2] concatenates arrays.'},
{id:1239,topic:'javascript',difficulty:'advanced',question:'What is a generator function?',options:['A function that generates random numbers','A function that can pause its execution and resume later, yielding multiple values','A function that creates other functions','An async function'],answer:1,explanation:'Generator functions (function*) use the yield keyword to pause execution and produce a sequence of values lazily. They return an iterator.'},
{id:1240,topic:'javascript',difficulty:'intermediate',question:'What does `for...of` iterate over?',options:['An object\'s own enumerable property keys','The values of an iterable (arrays, strings, Maps, Sets)','An object\'s prototype chain','Numeric indices only'],answer:1,explanation:'for...of iterates over the values of any iterable object (arrays, strings, Maps, Sets, generators). Use for...in for object property keys.'},
{id:1241,topic:'javascript',difficulty:'intermediate',question:'What is the difference between `for...in` and `for...of`?',options:['They are identical','for...in iterates over property keys; for...of iterates over iterable values','for...in is faster','for...of only works on arrays'],answer:1,explanation:'for...in enumerates all enumerable property keys (including inherited) of an object. for...of iterates over values of iterables like arrays, Maps, Sets.'},
{id:1242,topic:'javascript',difficulty:'beginner',question:'How do you convert a string to an integer?',options:['String.toInt()','parseInt()','Number.parseInt()','Both parseInt() and Number.parseInt()'],answer:3,explanation:'Both parseInt() and Number.parseInt() parse a string and return an integer. Number.parseInt is identical to the global parseInt function.'},
{id:1243,topic:'javascript',difficulty:'intermediate',question:'What does `localStorage.setItem("key","value")` do?',options:['Stores data in a cookie','Stores data persistently in the browser with no expiry','Stores data for the session only','Stores data in IndexedDB'],answer:1,explanation:'localStorage.setItem stores a key-value string pair persistently in the browser. Data survives page reloads and browser restarts until explicitly cleared.'},
{id:1244,topic:'javascript',difficulty:'intermediate',question:'What is the difference between localStorage and sessionStorage?',options:['localStorage is per-tab; sessionStorage persists across sessions','sessionStorage is cleared when the tab/window is closed; localStorage persists indefinitely','They are identical','sessionStorage supports larger data'],answer:1,explanation:'sessionStorage persists only for the duration of the page session (until the tab is closed). localStorage persists until explicitly cleared.'},
{id:1245,topic:'javascript',difficulty:'advanced',question:'What does `Symbol()` create?',options:['A unique string identifier','A unique and immutable primitive value used as a property key','A UUID string','A number'],answer:1,explanation:'Symbol() creates a unique, immutable primitive. Each Symbol() call returns a distinct value. Symbols are often used as unique object property keys to avoid name collisions.'},
{id:1246,topic:'javascript',difficulty:'intermediate',question:'What is `JSON.stringify()` used for?',options:['Parsing a JSON string into a JS object','Converting a JS value to a JSON-formatted string','Validating JSON','Deep cloning an object'],answer:1,explanation:'JSON.stringify() serializes a JavaScript value to a JSON string. JSON.parse() does the reverse. Note: functions, undefined, and Symbols are excluded.'},
{id:1247,topic:'javascript',difficulty:'intermediate',question:'What does `JSON.parse()` return when given a valid JSON string?',options:['A string','The original JavaScript value (object, array, number, etc.)','A Buffer','A Symbol'],answer:1,explanation:'JSON.parse() deserializes a JSON string into the corresponding JavaScript value — an object, array, number, string, boolean, or null.'},
{id:1248,topic:'javascript',difficulty:'beginner',question:'What is the `void` operator?',options:['Deletes a variable','Evaluates an expression and returns undefined','Checks if a variable is undefined','Converts to void pointer'],answer:1,explanation:'The void operator evaluates the given expression and returns undefined. Common use: void 0 as a reliable way to get undefined.'},
{id:1249,topic:'javascript',difficulty:'intermediate',question:'What does `Object.assign(target, source)` do?',options:['Deep clones source into target','Copies own enumerable properties from source to target','Creates a new object with merged properties','Freezes the target'],answer:1,explanation:'Object.assign() copies own enumerable string-keyed properties from one or more source objects to a target object. It performs a shallow copy.'},
{id:1250,topic:'javascript',difficulty:'intermediate',question:'What is optional chaining (`?.`)?',options:['A way to declare optional parameters','Short-circuits to undefined if the object before ?. is null/undefined instead of throwing','An async operator','A ternary shorthand'],answer:1,explanation:'Optional chaining (?.) returns undefined instead of throwing a TypeError if the referenced object is null or undefined, e.g., obj?.prop?.nested.'},
{id:1251,topic:'javascript',difficulty:'intermediate',question:'What is the nullish coalescing operator `??`?',options:['Returns the right operand if the left is falsy','Returns the right operand only if the left is null or undefined','Checks strict equality to null','A logical NOT operator'],answer:1,explanation:'?? returns the right-hand operand only when the left-hand side is null or undefined, unlike || which triggers on any falsy value (0, "", false).'},
{id:1252,topic:'javascript',difficulty:'advanced',question:'What does `Object.create(proto)` do?',options:['Copies proto into a new object','Creates a new object with proto as its prototype','Freezes proto','Clones proto deeply'],answer:1,explanation:'Object.create() creates a new object with the specified object as its prototype, enabling prototype-based inheritance without constructor functions.'},
{id:1253,topic:'javascript',difficulty:'intermediate',question:'What is the event loop?',options:['A loop that runs continuously checking for user input','A mechanism that processes the call stack and task queue to enable non-blocking async operations','A CSS animation loop','A server polling mechanism'],answer:1,explanation:'The event loop monitors the call stack and the task queue. When the call stack is empty, it moves tasks from the queue to the stack, enabling async JS.'},
{id:1254,topic:'javascript',difficulty:'advanced',question:'What are microtasks vs macrotasks?',options:['Microtasks run after macrotasks','Promise callbacks are microtasks (higher priority); setTimeout callbacks are macrotasks (lower priority)','They are the same thing','Macrotasks are synchronous'],answer:1,explanation:'Microtasks (Promise.then, queueMicrotask) have higher priority and run after the current task before the next macrotask. Macrotasks include setTimeout, setInterval, I/O.'},
{id:1255,topic:'javascript',difficulty:'intermediate',question:'What does `bind()` return?',options:['The result of calling the function','A new function with `this` permanently bound to the provided value','A Promise','An array of arguments'],answer:1,explanation:'Function.bind() returns a new function with this bound to the specified value (and optional pre-filled arguments). Unlike call/apply, it does not invoke immediately.'},
{id:1256,topic:'javascript',difficulty:'intermediate',question:'What is the difference between `call()` and `apply()`?',options:['call() is async; apply() is sync','call() takes arguments individually; apply() takes them as an array','apply() binds permanently; call() does not','They are identical'],answer:1,explanation:'Both call() and apply() invoke a function with a specified this. call() takes arguments individually: fn.call(ctx,a,b). apply() takes them as an array: fn.apply(ctx,[a,b]).'},
{id:1257,topic:'javascript',difficulty:'beginner',question:'What is a callback function?',options:['A function that calls itself','A function passed as an argument to another function, to be executed later','An immediately invoked function','An async function'],answer:1,explanation:'A callback is a function passed as an argument to another function. It is called ("called back") at a later point, often after an async operation completes.'},
{id:1258,topic:'javascript',difficulty:'intermediate',question:'What is "callback hell"?',options:['A callback that throws an error','Deeply nested callbacks that become hard to read and maintain','A callback that loops infinitely','Callbacks used in arrow functions'],answer:1,explanation:'Callback hell (pyramid of doom) refers to deeply nested callback functions that make code hard to read and debug. Promises and async/await solve this problem.'},
{id:1259,topic:'javascript',difficulty:'intermediate',question:'What does `Promise.race()` do?',options:['Returns all settled promises','Returns a promise that resolves/rejects with the value of the first settled promise','Races through array sequentially','Rejects if any promise rejects'],answer:1,explanation:'Promise.race() returns a promise that settles (resolves or rejects) as soon as the first promise in the iterable settles.'},
{id:1260,topic:'javascript',difficulty:'advanced',question:'What does `Promise.any()` do?',options:['Rejects if any promise rejects','Resolves with the first fulfilled promise; rejects only if ALL reject','Returns all results','Returns the slowest promise'],answer:1,explanation:'Promise.any() resolves with the first fulfilled value. It only rejects (with AggregateError) if all promises reject. This is the opposite of Promise.all().'},
{id:1261,topic:'javascript',difficulty:'intermediate',question:'What is the purpose of `async/await`?',options:['To run code in parallel threads','To write asynchronous code in a synchronous-looking style using Promises','To replace event listeners','To create generator functions'],answer:1,explanation:'async/await is syntactic sugar over Promises. An async function always returns a Promise. await pauses execution within the async function until the Promise settles.'},
{id:1262,topic:'javascript',difficulty:'intermediate',question:'What does `await` do inside an async function?',options:['Terminates the function','Pauses execution of the async function until the awaited Promise settles','Creates a new Promise','Converts a callback to a Promise'],answer:1,explanation:'await pauses the async function\'s execution and waits for the Promise to settle, then resumes with the resolved value (or throws on rejection).'},
{id:1263,topic:'javascript',difficulty:'beginner',question:'Which keyword is used to handle errors in async/await code?',options:['catch()','try...catch','error()','reject()'],answer:1,explanation:'In async/await code, try...catch blocks are used to handle errors (rejected promises). You can also chain .catch() on the returned promise.'},
{id:1264,topic:'javascript',difficulty:'intermediate',question:'What does `new` do when used with a function?',options:['Creates a copy of the function','Creates a new object, sets its prototype, executes the function with `this` bound to the new object','Calls the function with null context','Creates a class'],answer:1,explanation:'new: 1) Creates a new empty object, 2) Sets its prototype to the constructor\'s prototype, 3) Executes the constructor with this bound to the new object, 4) Returns the object.'},
{id:1265,topic:'javascript',difficulty:'intermediate',question:'What is the prototype chain?',options:['A CSS selector chain','A linked series of objects used for property lookup; if a property is not found on an object, JS searches up the chain','An array inheritance hierarchy','The DOM tree'],answer:1,explanation:'When a property is not found on an object, JS searches the object\'s prototype, then the prototype\'s prototype, up to Object.prototype, then returns undefined.'},
{id:1266,topic:'javascript',difficulty:'advanced',question:'What does `hasOwnProperty()` check?',options:['Whether an object has a property in its prototype chain','Whether an object has a property as a direct own property (not inherited)','Whether a property is writable','Whether a property is enumerable'],answer:1,explanation:'obj.hasOwnProperty("key") returns true only if the property is directly on the object, not inherited from the prototype chain.'},
{id:1267,topic:'javascript',difficulty:'intermediate',question:'What is a Set in JavaScript?',options:['An ordered list that allows duplicates','A collection of unique values','A key-value map','An immutable array'],answer:1,explanation:'A Set is a collection of unique values. Adding a duplicate value has no effect. Sets maintain insertion order and are iterable.'},
{id:1268,topic:'javascript',difficulty:'intermediate',question:'What is a Map in JavaScript?',options:['An array transformation method','A collection of key-value pairs where keys can be any type','A copy of an object','An asynchronous operation'],answer:1,explanation:'A Map holds key-value pairs where keys can be any type (objects, functions, primitives). It maintains insertion order and is iterable.'},
{id:1269,topic:'javascript',difficulty:'advanced',question:'What is the difference between Map and plain object `{}`?',options:['They are identical','Map keys can be any type; object keys are strings/Symbols. Maps have built-in size and are iterable by design.','Objects are faster','Maps are immutable'],answer:1,explanation:'Map allows any value as a key, has a .size property, guarantees insertion order, has no prototype key conflicts, and is directly iterable with for...of.'},
{id:1270,topic:'javascript',difficulty:'intermediate',question:'What does `Array.prototype.findIndex()` return?',options:['The matching element','The index of the first element satisfying the callback, or -1','All matching indices','The last matching index'],answer:1,explanation:'findIndex() returns the zero-based index of the first element that satisfies the callback. Returns -1 if no element matches.'},
{id:1271,topic:'javascript',difficulty:'beginner',question:'What does `String.prototype.trim()` do?',options:['Removes all spaces from a string','Removes whitespace from both ends of a string','Converts to lowercase','Splits the string'],answer:1,explanation:'trim() removes leading and trailing whitespace (spaces, tabs, newlines) from a string. trimStart()/trimEnd() target one side only.'},
{id:1272,topic:'javascript',difficulty:'intermediate',question:'What is the purpose of `Object.entries()`?',options:['Returns an array of the object\'s own enumerable string-keyed [key, value] pairs','Returns only the keys','Returns only the values','Returns the prototype entries'],answer:0,explanation:'Object.entries() returns an array of [key, value] pairs for all own enumerable string-keyed properties, useful for iteration and conversion to Map.'},
{id:1273,topic:'javascript',difficulty:'intermediate',question:'What is `globalThis`?',options:['The global object in Node.js only','A universal reference to the global object across all environments (browser: window, Node.js: global)','A browser-only property','A deprecated global variable'],answer:1,explanation:'globalThis provides a standard way to access the global object across environments. In browsers it is window; in Node.js it is global; globalThis works in both.'},
{id:1274,topic:'javascript',difficulty:'advanced',question:'What is tail call optimization?',options:['A way to optimize array loops','An optimization where the last function call in a function is optimized to avoid growing the call stack','A CSS optimization','A minification technique'],answer:1,explanation:'Tail call optimization (TCO) allows certain recursive calls in strict mode to be optimized by reusing the current stack frame, preventing stack overflow in deep recursion.'},
{id:1275,topic:'javascript',difficulty:'intermediate',question:'What does `Array.prototype.flatMap()` do?',options:['Flattens two levels of nesting','Maps each element and flattens the result by one level','Filters and maps simultaneously','Creates a 2D array'],answer:1,explanation:'flatMap() maps each element using a callback and then flattens the result one level deep. It is equivalent to arr.map(...).flat(1) but more efficient.'},
{id:1276,topic:'javascript',difficulty:'intermediate',question:'What is a higher-order function?',options:['A function with many parameters','A function that takes functions as arguments or returns a function','A function defined in the global scope','An immediately invoked function'],answer:1,explanation:'A higher-order function (HOF) accepts other functions as arguments and/or returns a function. Examples: map, filter, reduce, bind, compose.'},
{id:1277,topic:'javascript',difficulty:'intermediate',question:'What is function currying?',options:['Calling multiple functions in sequence','Transforming a function that takes multiple arguments into a sequence of functions each taking one argument','Binding function arguments','Composing functions'],answer:1,explanation:'Currying transforms f(a,b,c) into f(a)(b)(c). Each call returns a new function accepting the next argument, enabling partial application.'},
{id:1278,topic:'javascript',difficulty:'advanced',question:'What is memoization?',options:['Converting functions to strings','Caching the results of expensive function calls based on their inputs','A memory management technique','Lazy evaluation'],answer:1,explanation:'Memoization caches a function\'s return value for given arguments. On subsequent calls with the same arguments, the cached result is returned instead of recomputing.'},
{id:1279,topic:'javascript',difficulty:'intermediate',question:'What does `Object.values()` return?',options:['An array of the object\'s own enumerable property keys','An array of the object\'s own enumerable property values','An iterator of key-value pairs','The prototype values'],answer:1,explanation:'Object.values() returns an array of an object\'s own enumerable string-keyed property values, in the same order as for...in (but own only).'},
{id:1280,topic:'javascript',difficulty:'beginner',question:'What is event delegation?',options:['Assigning an event to multiple elements','Attaching a single event listener to a parent to handle events from child elements via bubbling','Preventing event bubbling','Creating custom events'],answer:1,explanation:'Event delegation leverages bubbling: one listener on a parent handles events from all current and future children, identified by event.target, improving performance.'},
{id:1281,topic:'javascript',difficulty:'intermediate',question:'What does `document.querySelector()` return?',options:['All matching elements as NodeList','The first element matching the CSS selector, or null','The parent element','The element\'s text content'],answer:1,explanation:'querySelector() returns the first Element that matches the specified CSS selector, or null if no match is found. querySelectorAll() returns all matches.'},
{id:1282,topic:'javascript',difficulty:'intermediate',question:'What is the difference between `innerHTML` and `textContent`?',options:['They are identical','innerHTML parses HTML; textContent treats content as plain text (safer, prevents XSS)','textContent is deprecated','innerHTML is faster'],answer:1,explanation:'innerHTML parses and renders HTML (XSS risk if from user input). textContent sets/gets plain text, ignoring HTML tags, and is safer for displaying user-provided content.'},
{id:1283,topic:'javascript',difficulty:'advanced',question:'What is a Web Worker?',options:['A background CSS thread','A script that runs in a background thread separate from the main UI thread','A service worker for caching','A DOM manipulation helper'],answer:1,explanation:'Web Workers run JavaScript in a background thread without blocking the UI. They communicate via postMessage/onmessage. They cannot access the DOM directly.'},
{id:1284,topic:'javascript',difficulty:'advanced',question:'What is a Service Worker?',options:['A background script that can intercept network requests, cache resources, and enable offline functionality','A Web Worker for DOM manipulation','A Node.js concept','A CSS preprocessor'],answer:0,explanation:'A Service Worker is a scriptable network proxy in the browser that intercepts fetch requests, caches assets, and enables Progressive Web App features like offline support.'},
{id:1285,topic:'javascript',difficulty:'intermediate',question:'What does `fetch()` return?',options:['The response body directly','A Promise that resolves to the Response object','An XMLHttpRequest object','A JSON object'],answer:1,explanation:'fetch() returns a Promise that resolves to the Response object representing the response. You then call .json(), .text(), or .blob() on it (also async).'},
{id:1286,topic:'javascript',difficulty:'intermediate',question:'What HTTP methods does fetch() support?',options:['GET only','GET and POST only','All HTTP methods via the method option in the options object','PUT and DELETE only'],answer:2,explanation:'fetch() supports all HTTP methods (GET, POST, PUT, DELETE, PATCH, etc.) specified in the second argument options object: fetch(url, {method:"POST",...}).'},
{id:1287,topic:'javascript',difficulty:'beginner',question:'What is CORS?',options:['A JavaScript framework','Cross-Origin Resource Sharing: a browser security mechanism that restricts cross-origin HTTP requests','A CSS layout system','A Node.js module'],answer:1,explanation:'CORS is a W3C specification that allows servers to declare which origins are permitted to access resources, overriding the browser\'s same-origin policy via HTTP headers.'},
{id:1288,topic:'javascript',difficulty:'intermediate',question:'What is a closure used for in module patterns?',options:['To prevent all variable access','To create private state by encapsulating variables in a function scope not accessible from outside','To improve performance','To create global variables'],answer:1,explanation:'The module pattern uses closures to create private state: variables in the outer function\'s scope are accessible to returned inner functions but not from outside the module.'},
{id:1289,topic:'javascript',difficulty:'advanced',question:'What is the difference between `__proto__` and `prototype`?',options:['They are identical','prototype is a property of constructor functions; __proto__ is the actual prototype link on object instances','__proto__ is for classes only','prototype is deprecated'],answer:1,explanation:'prototype is a property on constructor/class functions used to set up inheritance. __proto__ (or Object.getPrototypeOf()) is the actual prototype of an object instance.'},
{id:1290,topic:'javascript',difficulty:'intermediate',question:'What does `arguments` object contain inside a regular function?',options:['An array of the function\'s parameter names','An array-like object containing all arguments passed to the function','Only named parameters','The function\'s return value'],answer:1,explanation:'The arguments object is an array-like object (not an Array) available in non-arrow functions containing all passed arguments. Modern code prefers rest parameters (...args).'},
{id:1291,topic:'javascript',difficulty:'intermediate',question:'What are rest parameters (`...args`)?',options:['The spread operator used in reverse','A syntax that collects remaining function arguments into a true Array','A way to default parameters','An arguments object alias'],answer:1,explanation:'Rest parameters (...args) collect all remaining arguments into a real Array. Unlike the arguments object, rest parameters are Arrays and work in arrow functions.'},
{id:1292,topic:'javascript',difficulty:'intermediate',question:'What is a default parameter?',options:['A parameter that cannot be changed','A parameter with a fallback value used if the argument is undefined or not provided','A parameter that must be provided','A global parameter'],answer:1,explanation:'Default parameters allow function parameters to have a fallback value: function greet(name = "World") {}. The default is used if the argument is undefined.'},
{id:1293,topic:'javascript',difficulty:'beginner',question:'What does `typeof undefined` return?',options:['"null"','"undefined"','"object"','"void"'],answer:1,explanation:'typeof undefined returns the string "undefined". This is one of the few safe typeof checks — it does not throw even if the variable is undeclared.'},
{id:1294,topic:'javascript',difficulty:'intermediate',question:'What is the difference between a deep copy and a shallow copy?',options:['They are identical','A shallow copy copies references to nested objects; a deep copy creates independent copies of all nested objects','A deep copy is always faster','Shallow copies use more memory'],answer:1,explanation:'Shallow copy: nested objects share references. Deep copy: nested objects are fully duplicated. JSON.parse(JSON.stringify(obj)) is a simple deep copy (with limitations).'},
{id:1295,topic:'javascript',difficulty:'advanced',question:'What is the module system used in modern JavaScript (ES modules)?',options:['CommonJS require()','import/export syntax standardized in ES2015','AMD require()','UMD'],answer:1,explanation:'ES modules use import and export keywords. They are statically analyzable, support tree shaking, and are the standard in modern JS. Node.js also supports them with .mjs or "type":"module".'},
{id:1296,topic:'javascript',difficulty:'intermediate',question:'What does `export default` do?',options:['Exports all named exports','Defines the single default export of a module, imported without curly braces','Creates a global variable','Exports a constant only'],answer:1,explanation:'export default defines one default export per module. It is imported with: import MyName from \'./module\' (no curly braces). Named exports use curly braces on import.'},
{id:1297,topic:'javascript',difficulty:'intermediate',question:'What is tree shaking in JavaScript?',options:['Removing CSS styles','A bundler optimization that eliminates unused exports from the final bundle','Minifying code','Transpiling ES6 to ES5'],answer:1,explanation:'Tree shaking (dead code elimination) removes unused exports from a bundle. It relies on ES module static analysis. Tools like Webpack and Rollup perform tree shaking.'},
{id:1298,topic:'javascript',difficulty:'intermediate',question:'What does `requestAnimationFrame()` do?',options:['Sets a one-time timer','Schedules a callback before the next browser repaint, synced with the display refresh rate','Creates a CSS animation','Runs code in a Web Worker'],answer:1,explanation:'requestAnimationFrame() schedules a callback before the next screen repaint (~60fps), making animations smooth and efficient, pausing when the tab is not visible.'},
{id:1299,topic:'javascript',difficulty:'beginner',question:'What does `console.log()` do?',options:['Logs to a file','Outputs a message to the browser or Node.js console','Throws an error','Sends data to a server'],answer:1,explanation:'console.log() prints messages to the developer console. Other methods: console.error(), console.warn(), console.info(), console.table(), console.group().'},
{id:1300,topic:'javascript',difficulty:'intermediate',question:'What is the difference between `==` and `===` with `null` and `undefined`?',options:['They behave identically','null == undefined is true (loose), null === undefined is false (strict different types)','null === undefined is true','null == undefined is false'],answer:1,explanation:'null == undefined is true due to special loose equality rules. null === undefined is false because they are different types (Null vs Undefined).'},
{id:1301,topic:'javascript',difficulty:'advanced',question:'What is an IIFE (Immediately Invoked Function Expression)?',options:['A function defined inside a class','A function that invokes itself immediately upon definition, creating a private scope','A recursive function','An async function'],answer:1,explanation:'IIFE: (function() { ... })() — the function expression is immediately invoked. Used historically to create module-like private scopes before let/const/modules.'},
{id:1302,topic:'javascript',difficulty:'intermediate',question:'What does `Array.prototype.splice(start, deleteCount, ...items)` do?',options:['Returns a subarray without mutating','Mutates the array: removes deleteCount elements from start and optionally inserts items','Sorts the array','Flattens the array'],answer:1,explanation:'splice() mutates the original array: removes deleteCount elements from index start and inserts any provided items. Returns the removed elements.'},
{id:1303,topic:'javascript',difficulty:'intermediate',question:'What does `Array.prototype.slice(start, end)` do?',options:['Mutates the array by removing elements','Returns a shallow copy of a portion of the array without mutating the original','Sorts the array','Finds an element'],answer:1,explanation:'slice(start, end) returns a new array containing elements from start up to (not including) end. The original array is not modified.'},
{id:1304,topic:'javascript',difficulty:'intermediate',question:'What is the output of `typeof function(){}`?',options:['"object"','"function"','"callable"','"undefined"'],answer:1,explanation:'typeof applied to a function returns "function". Functions are objects in JS, but typeof distinguishes them with the special "function" string.'},
{id:1305,topic:'javascript',difficulty:'advanced',question:'What is the Revealing Module Pattern?',options:['A pattern using require()','A closure-based pattern where all logic is private and only a returned object literal reveals public members','A React pattern','A singleton pattern'],answer:1,explanation:'The Revealing Module Pattern encapsulates all variables/functions in a closure and returns an object that explicitly references the public API, improving readability over the standard module pattern.'},
{id:1306,topic:'javascript',difficulty:'intermediate',question:'What does `structuredClone()` do?',options:['Shallow copies an object','Creates a deep clone of an object using the structured clone algorithm, handling circular references','Serializes to JSON','Copies only enumerable properties'],answer:1,explanation:'structuredClone() (Web API, Node 17+) creates a deep clone supporting types JSON.parse/stringify cannot handle (Dates, RegExp, Map, Set, ArrayBuffer, circular refs).'},
{id:1307,topic:'javascript',difficulty:'intermediate',question:'What does the `delete` operator do?',options:['Removes a variable from scope','Removes a property from an object; returns true on success','Frees memory for garbage collection','Removes array elements by index'],answer:1,explanation:'delete obj.prop removes the property from the object. It returns true if successful. delete does not affect variables or array length (leaves undefined holes).'},
{id:1308,topic:'javascript',difficulty:'advanced',question:'What is Reflect in JavaScript?',options:['A mirror copy of an object','A built-in object providing methods for interceptable JS operations, designed to complement Proxy','A debugging tool','A form of metaprogramming only available in Node.js'],answer:1,explanation:'Reflect provides static methods matching Proxy handler traps (Reflect.get, Reflect.set, Reflect.has, etc.). It enables forwarding operations to the target in Proxy handlers.'},
{id:1309,topic:'javascript',difficulty:'intermediate',question:'What is `Array.prototype.every()` used for?',options:['Returns the first truthy element','Returns true only if ALL elements pass the callback test','Returns a filtered array','Reduces to a single value'],answer:1,explanation:'every() returns true if the callback returns truthy for every element. It short-circuits on the first falsy result. Returns true for an empty array (vacuous truth).'},
{id:1310,topic:'javascript',difficulty:'intermediate',question:'What does `String.prototype.split()` do?',options:['Joins array elements into a string','Splits a string into an array of substrings using a separator','Removes whitespace','Reverses a string'],answer:1,explanation:'split(separator) splits a string at each occurrence of the separator and returns an array of substrings. split("") gives individual characters.'},
{id:1311,topic:'javascript',difficulty:'beginner',question:'What does `Array.prototype.join()` do?',options:['Merges two arrays','Joins all array elements into a string using the specified separator','Splits the array','Sorts the array'],answer:1,explanation:'join(separator) concatenates all array elements into a string separated by the given separator (default comma). The reverse of String.split().'},
{id:1312,topic:'javascript',difficulty:'intermediate',question:'What is `setTimeout` used for?',options:['To execute code repeatedly at an interval','To execute a function once after a specified delay in milliseconds','To pause a script','To run code synchronously'],answer:1,explanation:'setTimeout(callback, delay) schedules callback to be called once after at least delay milliseconds. The actual delay may be longer due to event loop congestion.'},
{id:1313,topic:'javascript',difficulty:'intermediate',question:'What is `setInterval` used for?',options:['To execute a function once after a delay','To execute a function repeatedly at a specified interval in milliseconds','To cancel a timeout','To synchronize async calls'],answer:1,explanation:'setInterval(callback, interval) calls callback repeatedly every interval milliseconds until clearInterval() is called. Note: intervals can drift; requestAnimationFrame is better for animations.'},
{id:1314,topic:'javascript',difficulty:'advanced',question:'What is the output of `0.1 + 0.2 === 0.3`?',options:['true','false','undefined','NaN'],answer:1,explanation:'false. Due to IEEE 754 floating-point representation, 0.1 + 0.2 = 0.30000000000000004 in JS, not exactly 0.3. Use Number.EPSILON for comparisons.'},
{id:1315,topic:'javascript',difficulty:'intermediate',question:'What is the purpose of `Symbol.iterator`?',options:['A way to iterate over a Map','A well-known Symbol used to define the default iterator for an object, enabling for...of and spread','A getter for array length','A debugging helper'],answer:1,explanation:'Symbol.iterator is a well-known Symbol. When defined on an object as a method returning an iterator, it makes the object iterable (usable with for...of and spread).'},
{id:1316,topic:'javascript',difficulty:'advanced',question:'What is a tagged template literal?',options:['A template literal with variables','A template literal prefixed with a function that processes the template strings and interpolated values','A multi-line string','An escaped template literal'],answer:1,explanation:'A tagged template is tag`string ${expr}`. The tag function receives the string array and interpolated values, enabling DSLs like graphql`query{...}` or css`color:red`.'},
{id:1317,topic:'javascript',difficulty:'intermediate',question:'What does `Number.parseInt()` vs `parseInt()` do differently?',options:['Number.parseInt only handles base 10','They are identical — Number.parseInt is the same function as global parseInt','Number.parseInt throws on invalid input','parseInt accepts only strings'],answer:1,explanation:'Number.parseInt is identical to the global parseInt function. It was added to make the language more modular. Both parse a string argument to an integer.'},
{id:1318,topic:'javascript',difficulty:'intermediate',question:'What is `Array.prototype.indexOf()` used for?',options:['Finds the index of the first occurrence of a value using strict equality, or -1 if not found','Returns all indices of a value','Checks if a value exists','Returns the last index'],answer:0,explanation:'indexOf() uses strict equality (===) to find the first occurrence of a value in an array and returns its index, or -1 if not found. Not useful for finding NaN.'},
{id:1319,topic:'javascript',difficulty:'intermediate',question:'What is `Array.prototype.includes()` used for?',options:['Returns the index of an element','Returns true if the array contains the specified element (handles NaN correctly)','Checks object property existence','Filters elements'],answer:1,explanation:'includes() returns true/false. Unlike indexOf, it correctly handles NaN ([NaN].includes(NaN) === true). It uses the SameValueZero algorithm.'},
{id:1320,topic:'javascript',difficulty:'advanced',question:'What is the difference between `==` null checks and nullish checks?',options:['They are identical','== null catches both null and undefined; !== null only catches not null (not undefined)','=== null is preferred always','null checks throw errors'],answer:1,explanation:'x == null is true for both null and undefined (loose equality special case). x === null checks only for null. x != null is often used to filter both null and undefined.'},
{id:1321,topic:'javascript',difficulty:'intermediate',question:'What does `Array.from(new Set(array))` achieve?',options:['Sorts the array','Removes duplicate values from the array by converting to Set and back to Array','Flattens the array','Reverses the array'],answer:1,explanation:'new Set(array) removes duplicates (Sets only allow unique values). Array.from() converts the Set back to an Array. A concise deduplication pattern.'},
{id:1322,topic:'javascript',difficulty:'intermediate',question:'What does `String.prototype.padStart(targetLength, padString)` do?',options:['Trims from start','Pads the beginning of a string with padString until the string reaches targetLength','Pads the end','Converts to uppercase'],answer:1,explanation:'padStart pads the start of a string: "5".padStart(3,"0") gives "005". Useful for formatting numbers, timestamps, etc. padEnd pads the end.'},
{id:1323,topic:'javascript',difficulty:'intermediate',question:'What is the purpose of `Object.fromEntries()`?',options:['The same as Object.entries()','Transforms a list of [key, value] pairs or a Map into an object','Creates a frozen object','Deep clones an object from its entries'],answer:1,explanation:'Object.fromEntries() is the inverse of Object.entries(). It creates an object from an iterable of [key, value] pairs, e.g., new Map or the result of a .map() on entries.'},
{id:1324,topic:'javascript',difficulty:'advanced',question:'What is the Iterator Protocol?',options:['A browser API','An interface requiring a next() method that returns {value, done} objects','A Promise specification','A generator function requirement'],answer:1,explanation:'An iterator must have a next() method returning {value: any, done: boolean}. done:true signals the end. This protocol underpins for...of, spread, destructuring, and generators.'},
{id:1325,topic:'javascript',difficulty:'intermediate',question:'What does `Array.prototype.reverse()` do?',options:['Returns a reversed copy','Reverses the array IN PLACE and returns the reference to the same array','Sorts the array in descending order','Creates a new reversed array'],answer:1,explanation:'reverse() mutates the original array in place. To avoid mutation, create a copy first: [...arr].reverse() or arr.slice().reverse().'},
{id:1326,topic:'javascript',difficulty:'intermediate',question:'What is `Array.prototype.sort()` default behavior?',options:['Sorts numerically','Sorts elements as strings in UTF-16 code unit order by default','Sorts by array index','Does not sort; requires a comparator'],answer:1,explanation:'Default sort() converts elements to strings and sorts by UTF-16. This means [10,9,2].sort() gives [10,2,9]. Always provide a comparator for numeric sort: .sort((a,b)=>a-b).'},
{id:1327,topic:'javascript',difficulty:'intermediate',question:'What is `Array.prototype.fill(value, start, end)` used for?',options:['Fills missing values in sparse arrays','Fills all elements from start to end (exclusive) with value, mutating the array','Creates a new filled array','Replaces null values only'],answer:1,explanation:'fill() mutates the array, setting elements from index start to end-1 to value. [1,2,3].fill(0,1,2) gives [1,0,3].'},
{id:1328,topic:'javascript',difficulty:'advanced',question:'What is `BigInt` in JavaScript?',options:['A library for big numbers','A primitive type for integers of arbitrary size, denoted with n suffix: 9007199254740993n','A 64-bit float type','A specialized Number subclass'],answer:1,explanation:'BigInt (ES2020) represents integers larger than Number.MAX_SAFE_INTEGER. Created with literal n suffix (100n) or BigInt() function. Cannot mix with regular Number without explicit conversion.'},
{id:1329,topic:'javascript',difficulty:'intermediate',question:'What is `Array.prototype.at()` used for?',options:['Same as bracket notation','Accesses elements by index including negative indices (-1 for last element)','Checks if index exists','Slices from an index'],answer:1,explanation:'at() allows negative indices: arr.at(-1) returns the last element, arr.at(-2) second to last. Equivalent to arr[arr.length - 1] but more concise.'},
{id:1330,topic:'javascript',difficulty:'advanced',question:'What is the purpose of `Object.defineProperty()`?',options:['Creates a new property with a value only','Defines or modifies a property with full control over descriptor: value, writable, enumerable, configurable, get, set','Copies a property','Deletes a property'],answer:1,explanation:'Object.defineProperty() gives fine-grained control over property behavior: writable (can be reassigned), enumerable (shows in for...in), configurable (can be deleted/redefined), plus getter/setter.'}
]);
